{
  "implementation": "def solve(case):
    required = ['initial_state', 'max_steps', 'tool_observations', 'transitions']
    for key in required:
        if key not in case:
            raise ValueError(f"Missing required field: {key}")
    initial = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']
    current = initial
    steps = 0
    trace = []
    status = ''
    final = None
    while True:
        if current not in transitions:
            raise ValueError(f"State '{current}' not in transitions")
        state_def = transitions[current]
        if state_def.get('kind') == 'final':
            final = state_def.get('value')
            status = 'completed'
            break
        elif state_def.get('kind') == 'action':
            if steps >= max_steps:
                status = 'max_steps_reached'
                final = None
                break
            action = state_def.get('action')
            if action is None:
                raise ValueError("Action state missing 'action'")
            observation = tool_obs.get(action, 'invalid')
            next_by_obs = state_def.get('next_by_observation', {})
            default_next = state_def.get('default_next')
            if observation in next_by_obs:
                next_state = next_by_obs[observation]
            else:
                next_state = default_next
                if next_state is None:
                    raise ValueError(f"No next state for observation '{observation}' and no default")
            steps += 1
            trace.append({
                'step': steps,
                'action': action,
                'observation': observation,
                'state': next_state
            })
            current = next_state
        else:
            raise ValueError(f"Unknown state kind: {state_def.get('kind')}")
    return {
        'final': final,
        'status': status,
        'trace': trace
    }"
}
